cases.epl:
@name('table') create table MyTable(asum sum(int));
into table MyTable select sum(intPrimitive) as asum from SupportBean;
on SupportBean_S0 merge MyTable when matched then update set asum.reset();

@name('table') create table MyTable(asum sum(int));
into table MyTable select sum(intPrimitive) as asum from SupportBean;
on SupportBean_S0 merge MyTable as mt when matched then update set mt.reset();

@name('table') create table MyTable(k string primary key,   avgone avg(int), avgtwo avg(int),  winone window(*) @type(SupportBean), wintwo window(*) @type(SupportBean));
into table MyTable select theString,   avg(intPrimitive) as avgone, avg(intPrimitive) as avgtwo,  window(*) as winone, window(*) as wintwo from SupportBean#keepall group by theString;
on SupportBean_S0 merge MyTable where p00 = k  when matched then update set avgone.reset(), winone.reset();
on SupportBean_S1 merge MyTable where p10 = k  when matched then update set avgtwo.reset(), wintwo.reset();

@name('table') create table MyTable(  myAvedev avedev(int),
  myCount count(*),
  myCountDistinct count(distinct int),
  myMax max(int),
  myMedian median(int),
  myStddev stddev(int),
  myFirstEver firstever(string),
  myCountEver countever(*),  myMaxByEver maxbyever(intPrimitive) @type(SupportBean),  myPluginAggSingle myaggsingle(*),  myPluginAggAccess referenceCountedMap(string),  myWordcms countMinSketch());
into table MyTable select  avedev(intPrimitive) as myAvedev,  count(*) as myCount,  count(distinct intPrimitive) as myCountDistinct,  max(intPrimitive) as myMax,  median(intPrimitive) as myMedian,  stddev(intPrimitive) as myStddev,  firstever(theString) as myFirstEver,  countever(*) as myCountEver,  maxbyever(*) as myMaxByEver,  myaggsingle(*) as myPluginAggSingle,  referenceCountedMap(theString) as myPluginAggAccess,  countMinSketchAdd(theString) as myWordcms   from SupportBean#keepall;
on SupportBean_S0 merge MyTable mt when matched then update set mt.reset();
@name('s0') select MyTable.myWordcms.countMinSketchFrequency(p10) as c0 from SupportBean_S1;

create table IntrusionCountTable (
  fromAddress string primary key,
  toAddress string primary key,
  countIntrusion10Sec count(*),
  countIntrusion60Sec count(*)
);
create schema IntrusionReset(fromAddress string, toAddress string);
on IntrusionReset as resetEvent merge IntrusionCountTable as tableRow
where resetEvent.fromAddress = tableRow.fromAddress and resetEvent.toAddress = tableRow.toAddress
when matched then update set countIntrusion10Sec.reset(), countIntrusion60Sec.reset();
on IntrusionReset as resetEvent merge IntrusionCountTable as tableRow
where resetEvent.fromAddress = tableRow.fromAddress and resetEvent.toAddress = tableRow.toAddress
when matched then update set tableRow.reset();

